*/
scwin.btn_list_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_list_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.list()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods17010.btn_list_onclick' }); }
};


